class Solution {
public:
    int kthSmallest(vector<vector<int>>& mat, int k) {
        int m = mat.size();
        int n = mat[0].size();

        vector<int> sums(mat[0].begin(), mat[0].begin() + min(k, n));

        for (int r = 1; r < m; r++) {
            vector<int>& row = mat[r];
            int limit = min(k, n);
            priority_queue<pair<int, pair<int, int>>,
                           vector<pair<int, pair<int, int>>>,
                           greater<pair<int, pair<int, int>>>> pq;
            for (int i = 0; i < (int)sums.size(); i++) {
                pq.push({sums[i] + row[0], {i, 0}});
            }
            vector<int> next;
            int cnt = k;
            while (cnt > 0 && !pq.empty()) {
                pair<int, pair<int, int>> top = pq.top();
                pq.pop();
                next.push_back(top.first);
                int i = top.second.first;
                int j = top.second.second;
                if (j + 1 < limit) {
                    pq.push({sums[i] + row[j + 1], {i, j + 1}});
                }
                cnt--;
            }
            sums = move(next);
        }
        return sums[k - 1];
    }
};
